	const spy = sinon.spy();
	let errored;

	function Comp() {
		useEffect(() => {
			throw new Error('hi');
		});
		return null;
	}

	class App extends Component {
		componentDidCatch(err) {
			spy();
			errored = err;
			this.forceUpdate();
		}

